/* Owner-local natural Edna chase fixtures, generated by original D-pad/A.
 * Usage: test-qol-chase ROM ACTIVE_CHASE_STATE FLEEING_CHASE_STATE
 * Executes the production input adapter; no progression cheats or PC changes.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "../src/core/cart.h"
#include "../src/host/qol_input.h"

static nes_t initial, n, reference;
static unsigned failures;
#define CHECK(x) do { if (!(x)) { fprintf(stderr, "FAIL line %d: %s\n", __LINE__, #x); failures++; } } while (0)

static unsigned read_byte(nes_t *v, unsigned address) { return bus_peek(v, address); }
static unsigned active_x(nes_t *v, unsigned actor)
{
    unsigned slot = read_byte(v, 0x6d22 + actor);
    return slot < 4 ? read_byte(v, 0x6cbe + slot) : read_byte(v, 0x6b91 + actor);
}
static bool same_state(void)
{
    size_t size = nes_state_size();
    void *a = malloc(size), *b = malloc(size);
    uint8_t id[8] = {0};
    if (!a || !b) exit(5);
    nes_state_save(&n, a, id); nes_state_save(&reference, b, id);
    bool equal = !memcmp(a, b, size);
    free(a); free(b);
    return equal;
}
static void frame(qol_native_t *q, uint8_t pad)
{
    qol_native_update(&n, q, (qol_options_t){.hold_walk = true}, pad, true);
    nes_set_pad(&n, 0, pad); nes_run_frame(&n);
}
static bool load_fixture(const char *path, const uint8_t id[8])
{
    size_t size = nes_state_size(); void *buf = malloc(size);
    FILE *f = fopen(path, "rb");
    if (!f || !buf) { if (f) fclose(f); free(buf); return false; }
    size_t got = fread(buf, 1, size, f); fclose(f);
    bool ok = nes_state_load(&initial, buf, got, id);
    free(buf); return ok;
}
int main(int argc, char **argv)
{
    if (argc != 4) {
        fprintf(stderr, "usage: test-qol-chase ROM ACTIVE_CHASE_STATE FLEEING_CHASE_STATE\n"); return 2;
    }
    cart_t cart; char err[512];
    if (!cart_load(&cart, argv[1], false, err, sizeof err)) { fprintf(stderr, "%s\n", err); return 2; }
    nes_init(&initial, cart.prg, cart.prg_size);
    uint8_t id[8];
    for (unsigned i = 0; i < 8; i++) { unsigned b; sscanf(cart.prg_sha256 + i * 2, "%2x", &b); id[i] = b; }
    if (!load_fixture(argv[2], id)) return 3;
    CHECK(read_byte(&initial, 0x63c6) == 7);
    CHECK(read_byte(&initial, 0x6b0a) & 0x10);
    CHECK(active_x(&initial, 10) < 47);
    CHECK(active_x(&initial, 10) > active_x(&initial, 3));
    printf("natural starting pursuit: kidX%u EdnaX%u control%02x\n",
           active_x(&initial, 3), active_x(&initial, 10), read_byte(&initial, 0x6b0a));
    memcpy(&n, &initial, sizeof n); memcpy(&reference, &initial, sizeof reference);
    qol_native_t q; qol_native_init(&q);
    unsigned moved = 0, capture = 0, previous = active_x(&n, 10);
    for (unsigned i = 0; i < 90; i++) {
        uint8_t pad = i < 2 ? 0 : PAD_A;
        frame(&q, pad); nes_set_pad(&reference, 0, pad); nes_run_frame(&reference);
        CHECK(same_state());
        unsigned x = active_x(&n, 10); if (x != previous) moved++; previous = x;
        if (!(read_byte(&n, 0x6b0a) & 0x10)) capture++;
    }
    CHECK(moved > 0); CHECK(capture > 0);
    CHECK(!q.policy.holding_walk); CHECK(!q.last_walk_ms);
    CHECK(q.policy.blocked); CHECK(!n.exec_hook);
    frame(&q, 0); CHECK(!q.policy.blocked); CHECK(!q.policy.holding_walk);
    printf("stationary hold: 90 full native states equal, pursuit moves=%u capture frames=%u, neutral drain verified\n", moved, capture);

    if (!load_fixture(argv[3], id)) return 3;
    CHECK(read_byte(&initial, 0x63c6) == 7);
    CHECK(read_byte(&initial, 0x6b0a) & 0x10); CHECK(active_x(&initial, 10) < 47);
    memcpy(&n, &initial, sizeof n); qol_native_init(&q);
    frame(&q, 0); frame(&q, 0);
    unsigned retargets = 0; uint64_t last = 0;
    uint8_t direction = read_byte(&n, 0x7116) < 128 ? PAD_RIGHT : PAD_LEFT;
    for (unsigned i = 0; i < 20; i++) {
        frame(&q, PAD_A | direction);
        if (q.last_walk_ms != last) { retargets++; last = q.last_walk_ms; }
    }
    CHECK(retargets > 0); last = q.last_walk_ms;
    unsigned release_updates = 0;
    for (unsigned i = 0; i < 35; i++) {
        frame(&q, direction);
        if (q.last_walk_ms && q.last_walk_ms != last) release_updates++;
        last = q.last_walk_ms;
    }
    CHECK(!q.policy.holding_walk); CHECK(release_updates == 0);
    printf("moving hold in natural chase: retargets=%u release updates=%u room=%u control=%02x failures=%u\n",
           retargets, release_updates, read_byte(&n, 0x63c6), read_byte(&n, 0x6b0a), failures);
    cart_free(&cart);
    return failures ? 1 : 0;
}
